    const conf = ev.filter(e => e.conf === 'confirmado').length, gap = !f.pasta && !ev.length ? 'crítica' : lac.length >= 3 ? 'relevante' : lac.length ? 'pequena' : 'sem lacuna';
    const pergCrit = (gap === 'relevante' || gap === 'crítica') && lac.includes('data de ciência ou publicação') && /prazo/.test(n) ? 'Qual é a data de ciência ou de publicação? Com ela consigo dizer se o prazo está seguro.' : !f.pasta ? 'De qual pasta estamos falando?' : null;
