    if (!['pesquisar', 'pesquisas', 'monitorar', 'subutilizadas'].includes(k)) return null;
    const base = { modulos: ['Pesquisa'], comando: 'Pesquisa', pontos: [], acoes: [] };
    if (k === 'subutilizadas') { const usos = {}; Object.values(skillsK()).forEach(s => (s.usos || []).forEach(u => { usos[u.cmd] = (usos[u.cmd] || 0) + 1; })); const nunca = COMANDOS_IA.filter(x => !usos[x.c] && !x.eq).slice(0, 10); return { ...base, resposta: nunca.length + ' recurso(s) da IA ainda não foram usados nesta conta. Antes de pedir algo novo, vale ver se um destes resolve.', secoes: [{ titulo: 'Pouco usados', itens: nunca.map(x => '/' + x.c + ' · ' + x.t + ' · ' + x.d) }] }; }
    if (k === 'pesquisas') { const P = (nucleo().pesquisas || []).slice(-8).reverse(); return { ...base, resposta: P.length + ' pesquisa(s) recente(s).', secoes: [{ titulo: 'Como a IA chegou às respostas', itens: P.map(p => dataTK(p.em) + ' · "' + p.pergunta + '" · ' + p.camadas.length + ' camada(s) · ' + p.evid + ' evidência(s), ' + p.conf + ' confirmada(s) · lacuna ' + p.gap + ' · ' + p.destino) }] }; }
    if (k === 'monitorar') { const N = nucleo(); N.monitor = N.monitor || {}; const f = window.__bjIAFontes ? window.__bjIAFontes() : {}, alvos = { regras: () => JSON.stringify(nucleo().regras.map(r => [r.id, r.versao, r.ativa])), pje: () => JSON.stringify(f.processo && f.processo.pje || null), situacao: () => f.pasta && f.pasta.situacao, responsavel: () => f.pasta && f.pasta.responsavel };
      const q = norm((cmd && cmd.arg) || ''), sel = Object.keys(alvos).filter(x => !q || q.includes(x)); sel.forEach(x => { N.monitor[x + ':' + ((f.pasta || {}).numero || '')] = { h: hashK(alvos[x]() || ''), em: Date.now() }; }); salvar(); return { ...base, resposta: 'Monitorando: ' + sel.join(', ') + '. Quando mudar, aviso "conhecimento monitorado sofreu alteração".' }; }
