    if (sistema) { const V = verificadores(), inc = V.filter(a => /interface|referência|duplic|temporal|impossível/.test(a.tipo)), rg = nucleo().regras.filter(r => r.ativa && /permiss|acesso|nunca/.test(norm(r.texto)));
      return { ...base, resposta: inc.length ? 'Encontrei ' + inc.length + ' inconsistência(s) que podem explicar a diferença.' : 'Não encontrei inconsistência nos dados que esta tela enxerga; a diferença provavelmente está no servidor ou em outro filtro de período.', secoes: [{ titulo: 'Inconsistências', itens: inc.length ? inc.map(a => a.mod + ' · ' + a.desc + ' · evidência: ' + a.evid) : ['Nenhuma'] }, { titulo: 'Onde a informação fica', itens: ['Tela: dados recebidos pela página aberta', 'Navegador: bj-central-v1 (Chat e núcleo), bj-metas-pasta-v1 (metas), bj-clientes-v1 (cadastro), bj-push-links-v1 (links)', 'Servidor, banco e logs: fora do alcance do protótipo'] }, { titulo: 'Regras que podem bloquear', itens: rg.map(r => r.id + ' · ' + r.texto).concat(['Seu perfil: ' + perf.papel]) }], acoes: [{ tipo: 'enviar_comando', rotulo: 'Ver incidentes', texto: '/incidentes' }] }; }
    if (prazoQ) { const f = filtrarAcesso(window.__bjIAFontes ? window.__bjIAFontes() : {}, perf), it = (f.push || []).filter(p => /intima|publica|citac/.test(norm(p.tipo))), ult = it[0], pje = f.processo && f.processo.pje, cien = ult && (ult.ciencia || ult.dataCiencia);
      return { ...base, resposta: !ult ? 'Não localizei intimação ou publicação nesta pasta; sem o ato, não há prazo a calcular.' : cien ? 'A ' + ult.tipo.toLowerCase() + ' de ' + ult.data + ' tem ciência em ' + cien + '. Conte o prazo a partir do primeiro dia útil seguinte, conforme o ato.' : 'Localizei a ' + ult.tipo.toLowerCase() + ' de ' + ult.data + ' (' + (ult.fonte || 'Push') + '), mas não há data de ciência registrada. Sem ela, não afirmo o termo final.', secoes: ult ? [{ titulo: 'Evidências', itens: [ult.tipo + ' · ' + ult.data + ' · ' + String(ult.texto || '').slice(0, 120), 'Meta correspondente: ' + ((f.metas || []).some(m => tokensK(m.titulo).filter(w => tokensK(ult.texto).includes(w)).length >= 2) ? 'sim' : 'não localizada'), 'Dados do PJe: ' + (pje ? 'disponíveis' : 'não buscados')] }, { titulo: 'O que falta', itens: cien ? ['Confirmar o tipo do prazo pelo teor do ato'] : ['Data de ciência ou de publicação', 'Tipo do ato (prazo comum, em dobro, específico do juízo)'] }] : [], pontos: [{ nivel: 'info', camada: 'hipotese', confianca: 'provavel', texto: 'Qual é a data de ciência? Com ela consigo calcular o termo final em dias úteis.' }] }; }
    const P = pesquisar(q, perf), ok = P.H.filter(h => h.ok), nok = P.H.filter(h => !h.ok);
