    if (k === 'capacidade') { let e = null; try { e = estGarantir(perf).e; } catch (x) {} const precisa = R.M.paradas, livres = folga.length; return { ...base, comando: 'Capacidade × estratégia', resposta: (e ? 'Para a estratégia "' + e.objetivo + '", ' : '') + 'é preciso tratar ' + precisa + ' pasta(s) parada(s). ' + (livres ? 'Há folga em ' + folga.map(q => q.nome).join(', ') + ': dá para executar sem contratar, se essa folga for reservada.' : 'Ninguém está com folga clara: a estratégia exige mais capacidade do que a equipe tem livre hoje. Opções: reservar um horário semanal, reduzir escopo ou alongar o prazo.'), secoes: [{ titulo: 'Reserva sugerida', itens: ['Manter uma reserva para prazos críticos: não comprometer 100% de ninguém com as pastas paradas.'] }, { titulo: 'O que ainda não sei', itens: [limite] }] }; }
    if (k === 'estresse') { const cen = [['Perde 10% da capacidade', 1.1], ['Perde 20% da capacidade', 1.25], ['Demanda +30%', 1.3]].map(([n, f]) => { const q = R.lista.find(x => x.carga * f >= R.media * 1.5 && x.carga * f >= 3); return n + ': ' + (q ? 'quebra primeiro em ' + q.nome + ' (' + Math.round(q.carga * f / R.media * 100) + '% da média)' : 'ninguém passa do limite'); }); const fora = R.spof[0] || top; return { ...base, comando: 'Teste de estresse', resposta: 'Simulei a equipe sob pressão (é projeção, nada real foi alterado):', secoes: [{ titulo: 'Cenários', itens: cen }, { titulo: 'E se ' + (fora ? fora.nome : 'a pessoa com mais carga') + ' ficar indisponível?', itens: fora ? [fora.pastas + ' pasta(s) e ' + fora.metas + ' meta(s) ficam sem dono. Efeito em cadeia: menos capacidade → atraso → acúmulo → sobrecarga de quem assumir → mais risco de prazo.'] : ['Sem dados.'] }, { titulo: 'O que ainda não sei', itens: [limite] }], pontos: [{ nivel: 'monitorar', camada: 'hipotese', confianca: 'provavel', texto: 'Simulação com base na carga atual' }] }; }
