    if (k === 'clientes') { const risco = M.lista.filter(q => ['RISCO', 'CRÍTICO'].includes(q.saude)); return { ...base, comando: 'Saúde dos clientes', resposta: M.lista.length + ' cliente(s) na carteira: ' + ['SAUDÁVEL', 'ATENÇÃO', 'RISCO', 'CRÍTICO'].map(s => M.lista.filter(q => q.saude === s).length + ' ' + s.toLowerCase()).join(', ') + '.' + (risco.length ? ' Os de maior risco têm sinais compatíveis com perda da relação; abaixo, o porquê de cada um.' : ''), secoes: [{ titulo: 'Clientes por saúde', itens: M.lista.map(q => ic[q.saude] + ' ' + q.cli + ' · ' + q.saude + (q.sinais.length ? ' · ' + q.sinais.map(s => s.t).slice(0, 2).join('; ') : '')) }, { titulo: 'Possível expansão (hipótese)', itens: M.lista.filter(q => q.pj && q.saude !== 'CRÍTICO').map(q => q.cli + ' é pessoa jurídica com ' + q.pastas.length + ' pasta(s): empresas costumam ter outras demandas (trabalhista, contratos, cobrança). Confirmar a necessidade com o cliente antes de qualquer proposta.').concat(M.lista.some(q => q.pj && q.saude !== 'CRÍTICO') ? [] : ['Nenhuma evidência suficiente.']) }, { titulo: 'O que ainda não sei', itens: [sem, 'A saúde usa só sinais de operação e financeiro; sem pesquisa de satisfação, não sei como o cliente percebe o atendimento.'] }], pontos: risco.slice(0, 3).map(q => ({ nivel: q.saude === 'CRÍTICO' ? 'critico' : 'atencao', camada: 'analise', confianca: 'provavel', texto: q.cli + ': ' + q.saude, motivo: q.sinais.map(s => s.t).join('; ') })), acoes: risco.slice(0, 2).map(q => ({ tipo: 'abrir_pasta', rotulo: 'Abrir ' + q.cli.split(' ')[0], pasta: q.pastas[0].num })) }; }
