  const PROMESSA = /\b(vou (te )?(retornar|responder|verificar|enviar|mandar|cobrar|protocolar|ver isso|resolver)|te (mando|envio|retorno)|amanha (eu )?(resolvo|mando|envio|retorno)|vamos protocolar)\b/;
