    if (/prazo .{0,25}(e|vence|termina|ate) .{0,15}(\d{1,2}\/\d{1,2}|segunda|terca|quarta|quinta|sexta|amanha)/.test(t)) A.push(['médio', 'Menciona prazo: confira na movimentação oficial antes de enviar.']);
    if (/\d{3}\.?\d{3}\.?\d{3}-?\d{2}|\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2}/.test(txt)) A.push(['médio', 'Contém CPF/CNPJ: envie só se o destinatário precisar desse dado (LGPD).']);
    if (/(pagou|pagamento (foi )?(feito|confirmado)|ja esta pago)/.test(t)) A.push(['médio', 'Afirma pagamento: confirme no Financeiro antes; mensagem do cliente não é comprovante.']);
    if (/(absurdo|irresponsavel|incompetente|vergonha|ridiculo)/.test(t)) A.push(['médio', 'Tom pode soar agressivo; considere reescrever de forma neutra.']);
    if (PROMESSA.test(t)) A.push(['baixo', 'Contém compromisso de retorno: vou acompanhar e te lembro se não houver retorno.']);
