    const P = D.push.slice().sort((a, b) => dn(a.data) - dn(b.data)), tem = re => P.some(m => re.test(norm(m.tipo + ' ' + m.texto)));
    const fases = [['Execução / cumprimento', /cumprimento de sentenca|penhora|execu/], ['Recurso', /apelac|agravo|recurso/], ['Sentença', /senten/], ['Instrução', /audiencia|pericia|instruc/], ['Réplica', /replica/], ['Defesa', /contesta/], ['Citação', /cita/], ['Distribuição / inicial', /distribu|inicial/]];
    const ult = P[P.length - 1], fase = (ult && fases.find(([n, re]) => re.test(norm(ult.tipo + ' ' + ult.texto)))) || fases.find(([n, re]) => tem(re));
    const fatos = P.map(m => ['Movimentação: ' + m.tipo, m.data, 'oficial (' + m.fonte + ')', 'comprovado']);
    D.checklist.forEach(x => { const w = norm(x.titulo).split(' ')[0], doc = D.docs.find(d => norm(d.nome).includes(w)); fatos.push([x.titulo, doc ? doc.data : '', doc ? 'documento ' + doc.nome : 'checklist', x.ok && doc ? 'comprovado' : x.ok ? 'declarado sem arquivo' : doc ? 'conflito (arquivo existe, checklist diz que falta)' : 'não comprovado']); });
    const semMeta = tem(/intima/) && !D.metas.some(m => !m.concluida && /manifest|replica|respond/i.test(m.titulo)), q = [], riscos = [];
    if (D.proc && /cumprimento de senten/i.test(D.proc.classe || '') && tem(/cita|contesta|replica/)) q.push('A classe cadastrada é "Cumprimento de sentença", mas a sequência (citação, contestação, réplica) é de fase de conhecimento. Conferir a classe no PJe.');
    if (tem(/tutela|liminar/)) q.push('Há tutela/liminar na sequência: verificar cumprimento da decisão e eventual multa, com base no texto da decisão.');
    if (semMeta) q.push('Intimação sem meta de manifestação aberta: confirmar prazo e quem age.');
