    if (cm) add('Comunicação', 'Mensagem urgente respondida no mesmo dia', 'Destinatário', cm.aguardando.filter(x => x.nivel === 'urgente' && x.horas > 8).map(x => x.quem + ' · ' + x.horas + 'h'), 'alto', 'Responder (/aguardando)');
    if (cm) add('Comunicação', 'Promessa de retorno é cumprida', 'Quem prometeu', cm.promessas.map(x => x.quem + ' · ' + x.dias + ' dia(s)'), 'médio', 'Retornar ao contato');
