  function agSaude() { const L = mzK(), uso = {}, ok = {}; L.forEach(m => m.equipe.forEach(a => { uso[a] = (uso[a] || 0) + 1; if (m.concluida) ok[a] = (ok[a] || 0) + 1; })); return Object.keys(AGT).map(k => { const u = uso[k] || 0, mat = u === 0 ? 0 : u < 3 ? 1 : u < 10 ? 2 : (ok[k] || 0) / u > .8 ? 3 : 2; return [k, AGT[k].nome, u, u ? Math.round((ok[k] || 0) / u * 100) : null, mat]; }); }
