    if (!txt) { try { const fb = cogResposta('tem alguma pendencia nesta pasta', { c: 'investigar', arg: '' }, perf); if (fb && fb.resposta) { auditar('autocura', 'motor indisponível; respondi com os módulos locais', 'ok'); fb.pontos = [{ nivel: 'info', camada: 'dado', confianca: 'confirmado', texto: 'A inteligência principal não respondeu; usei a análise local da pasta.' }].concat(fb.pontos || []); salvarResp('A inteligência principal não respondeu agora, então fiz a análise com o que tenho aqui: ' + fb.resposta, fb); return; } } catch (e) {} }
    if (!txt) { salvarResp('Ih, ' + EU().nome.split(' ')[0] + ', perdi a conexão com a inteligência agora 😕 Tenta de novo em instantes?', null); return; }
    const d = parseIA(txt); d.resposta = humanizar(d.resposta); if (d.pergunta) d.pergunta = humanizar(d.pergunta);
