    d.secoes = (d.secoes || []).slice(0, 6).filter(s => s && s.titulo && Array.isArray(s.itens)).map(s => ({ titulo: semTraco(s.titulo), itens: s.itens.slice(0, 6).map(semTraco) }));
    const pr = ctx.produtividade || {}; d.fonte = { escopo: pr.escopo, referencia: pr.referencia, semana: pr.semana, modulos: d.modulos, colaboradores: (pr.usuarios || []).filter(u => !cmd || !cmd.arg || norm(u.nome).includes(norm(cmd.arg).split(' ')[0])).slice(0, 8) };
    d.acoes = (d.acoes || []).filter(a => a && a.tipo).slice(0, 4);
    if (d.trace && typeof d.trace === 'object') { const N3 = nucleo(); N3.traces = (N3.traces || []).concat([{ em: Date.now(), pedido: pedido.slice(0, 120), ...d.trace }]).slice(-60); }
    salvarResp(d.resposta, d);
