  const NIVEL_IA = { critico: ['#c0392b', 'Crítico'], atencao: ['#e8590c', 'Atenção'], monitorar: ['#c9a227', 'Monitorar'], ok: ['#1e7b45', 'Normal'], oportunidade: ['#1f6fd1', 'Oportunidade'] };
