    b.style.cssText = 'position:absolute;top:' + (usaHead ? '50%' : '8px') + ';right:8px;' + (usaHead ? 'transform:translateY(-50%);' : '') + 'z-index:5;width:26px;height:26px;border:none;border-radius:4px;display:flex;align-items:center;justify-content:center;cursor:pointer;transition:background .15s,color .15s;background:' + (escuro ? 'rgba(255,255,255,.14)' : 'rgba(238,243,246,.95)') + ';color:' + (escuro ? '#fff' : '#4f6878');
