    b.onmouseleave = () => { b.style.background = escuro ? 'rgba(255,255,255,.14)' : 'rgba(238,243,246,.95)'; b.style.color = escuro ? '#fff' : '#4f6878'; };
    b.addEventListener('pointerdown', e => e.stopPropagation(), true); b.addEventListener('mousedown', e => e.stopPropagation(), true);
    b.addEventListener('click', e => { e.preventDefault(); e.stopPropagation(); fechar(jan, base); });
    if (usaHead) { const pr = parseFloat(getComputedStyle(h).paddingRight) || 0; if (pr < 40) h.style.paddingRight = (pr + 34) + 'px'; }
    host.appendChild(b);
