  let agendado = false;
  function varrer() {
    agendado = false;
    document.querySelectorAll('[role="menu"],[role="dialog"],[role="alertdialog"],[role="listbox"]').forEach(el => { if (el.parentElement && el.parentElement.closest('[role="menu"],[role="dialog"],[role="alertdialog"],[role="listbox"]')) return; colocar(el); });
    document.querySelectorAll('[style*="position: fixed"],[style*="position:fixed"]').forEach(el => { if (el.dataset && el.children.length && cobre(el) && !el.closest('[data-sem-x]')) { const k = alvo(el); if (k && getComputedStyle(k).boxShadow !== 'none') colocar(el); } });
  }
  new MutationObserver(() => { if (!agendado) { agendado = true; requestAnimationFrame(() => setTimeout(varrer, 30)); } }).observe(document.documentElement, { childList: true, subtree: true });
