/* ---------- Dicas adaptativas (balão de ajuda nos botões pouco usados) ----------
   Regra: aparece só ao passar o cursor (após 0,6s) em botões do catálogo que a pessoa ainda não domina.
   Some ao sair ou após 8s. Para de aparecer quando: a pessoa usou o botão 3 vezes, clicou em "Entendi",
   ou já viu a dica 4 vezes sem usar (volta 1 vez após 30 dias). Quem já domina 12 ferramentas vira
   "usuário experiente" e as dicas desligam sozinhas. Tudo por usuário. /dicas no Chat I.A mostra e controla. */
(function () {
  if (window.__bjDicas) return; window.__bjDicas = true;
  const CAT = [
    ['vincular', /^vincular ao cadastro$/i, 'Liga este arquivo do menu Documentos ao cadastro do cliente, sem copiar. Vale para todas as pastas desse CPF.'],
    ['validar', /^validar( todas)?$/i, 'Aceita a sugestão da IA e grava no cadastro. Fica no Histórico com o documento de origem.'],
    ['manter', /^manter anterior$/i, 'Mantém o valor que já estava no cadastro e descarta a sugestão desta vez.'],
    ['qualif', /^copiar qualifica[cç][aã]o$/i, 'Copia a qualificação completa do cliente pronta para colar em petições e contratos.'],
    ['linhaid', /linha do tempo da identidade/i, 'Mostra em ordem cada documento que confirmou nome, CPF e endereço do cliente.'],
    ['apensado', /^\d+ apensados?$/i, 'Mostra os processos apensados a este, como embargos, com número e situação.'],
    ['trocar', /^trocar$/i, 'Troca o processo vinculado a esta pasta. A busca vem do menu Processo.'],
    ['cadastro', /^cadastro$/i, 'Abre a ficha completa do cliente. A bolinha âmbar indica pendências no cadastro.'],
    ['anexar', /^anexar$/i, 'Envia o arquivo do seu computador e já marca o item do checklist como entregue.'],
    ['linkpush', /link externo do push|ver como terceiro/i, 'Gera um link para o cliente acompanhar o processo sem login. Vale 30 dias e conta os acessos.'],
    ['resumir', /resumir com ia|gerar nova an[aá]lise/i, 'A IA lê as movimentações e resume o que aconteceu, se há prazo e o que fazer. Não altera nada oficial.'],
    ['sugdoc', /sugerir documento/i, 'A IA sugere a peça adequada ao momento do processo, com base nas movimentações e no histórico do escritório.'],
    ['encaminhar', /encaminhar via chat i\.?a|^despachar$/i, 'Envia este item para um colega ou grupo pelo Chat I.A, com instrução e prioridade.'],
    ['criartarefa', /^criar tarefa$/i, 'Transforma esta movimentação em uma meta com prazo e responsável.'],
    ['intel', /bluejus\s*intelligence/i, 'Painel de análise da pasta: riscos, pendências e próximos passos sugeridos pela IA.'],
    ['avancado', /modo avan[cç]ado/i, 'Liga as análises completas da IA sobre o escritório. Fica salvo só para você.'],
    ['exportar', /^exportar pdf$|^baixar arquivo$/i, 'Gera o arquivo com tarja azul e logo, pronto para enviar ou arquivar.'],
    ['ativo', /^(ativo|suspenso|arquivado|cancelado)$/i, 'Muda a situação da pasta. Arquivar ou cancelar fica registrado e aparece como carimbo no cabeçalho.'],
  ];
  const K = 'bj-dicas-v1', USOS = 3, VISTAS = 4, VOLTA = 30 * 864e5, EXPERT = 12;
  const uid = () => { try { return window.BJCentral ? window.BJCentral.eu().id : 'eu'; } catch (e) { return 'eu'; } };
  const ler = () => { try { return JSON.parse(localStorage.getItem(K) || '{}'); } catch (e) { return {}; } };
  const st = () => { const a = ler(), u = a[uid()] = a[uid()] || { u: {}, v: {}, ok: {}, vt: {}, desl: false }; return [a, u]; };
  const grava = a => { try { localStorage.setItem(K, JSON.stringify(a)); } catch (e) {} };
  const limpa = s => String(s || '').replace(/\s+/g, ' ').trim();
  const achar = el => { for (const t of [limpa(el.textContent), limpa(el.getAttribute('aria-label')), limpa(el.getAttribute('title'))]) { if (!t || t.length > 60) continue; const it = CAT.find(x => x[1].test(t)); if (it) return it; } return null; };
  const experiente = u => Object.values(u.u).filter(n => n >= USOS).length >= EXPERT;
  function deveMostrar(u, k) { if (u.desl || u.ok[k] || experiente(u) || (u.u[k] || 0) >= USOS) return false; const v = u.v[k] || 0; if (v < VISTAS) return true; return Date.now() - (u.vt[k] || 0) > VOLTA && v < VISTAS + 1; }
  let bal = null, alvo = null, tmr = 0, auto = 0, tit = null, t0 = Date.now();
  function fechar() { clearTimeout(tmr); clearTimeout(auto); if (bal) { bal.remove(); bal = null; } if (alvo && tit != null) { alvo.setAttribute('title', tit); } tit = null; alvo = null; }
  function mostrar(el, item) {
    fechar(); const [a, u] = st(); if (!deveMostrar(u, item[0])) return;
    u.v[item[0]] = (u.v[item[0]] || 0) + 1; u.vt[item[0]] = Date.now(); grava(a); alvo = el;
    if (el.hasAttribute('title')) { tit = el.getAttribute('title'); el.removeAttribute('title'); }
    const b = document.createElement('div'); b.setAttribute('role', 'tooltip');
    b.style.cssText = 'position:fixed;z-index:2147483600;max-width:300px;padding:9px 11px 8px;background:#e3f1fa;color:#0b4f73;border:1px solid #b9dcf0;border-radius:4px;box-shadow:0 6px 18px -8px rgba(12,70,105,.35);font:12.5px/1.45 Arial,Helvetica,sans-serif;opacity:0;transform:translateY(4px);transition:opacity .18s,transform .18s';
    const visto = u.v[item[0]], resta = Math.max(0, USOS - (u.u[item[0]] || 0));
    b.innerHTML = '<div style="display:flex;align-items:center;gap:6px;margin-bottom:3px;font-size:10.5px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#0a6a96"><i class="bi bi-lightbulb" style="font-size:12px"></i>Dica</div><div></div><div style="display:flex;align-items:center;gap:12px;margin-top:7px;font-size:11.5px;white-space:nowrap"><button data-a="ok" style="border:none;background:none;padding:0;color:#0a6a96;font:inherit;font-weight:700;cursor:pointer">Entendi</button><button data-a="off" style="border:none;background:none;padding:0;color:#4f7891;font:inherit;cursor:pointer">Não mostrar dicas</button><span title="Depois de ' + resta + ' uso(s) deste botão a dica não aparece mais" style="margin-left:auto;color:#6a92aa;font-size:10.5px">' + resta + '/' + USOS + '</span></div><span style="position:absolute;width:9px;height:9px;background:#e3f1fa;border-left:1px solid #b9dcf0;border-top:1px solid #b9dcf0;left:var(--ax,20px)"></span>';
    b.children[1].textContent = item[2];
    b.addEventListener('mouseenter', () => clearTimeout(auto)); b.addEventListener('mouseleave', () => { auto = setTimeout(fechar, 400); });
    b.addEventListener('click', e => { const x = e.target.closest('[data-a]'); if (!x) return; const [a2, u2] = st(); if (x.dataset.a === 'ok') u2.ok[item[0]] = Date.now(); else u2.desl = true; grava(a2); fechar(); });
    document.body.appendChild(b); bal = b;
    const r = el.getBoundingClientRect(), bw = b.offsetWidth, bh = b.offsetHeight, emb = r.bottom + bh + 12 < innerHeight;
    const left = Math.max(8, Math.min(innerWidth - bw - 8, r.left + r.width / 2 - bw / 2)), top = emb ? r.bottom + 9 : r.top - bh - 9;
    b.style.left = left + 'px'; b.style.top = top + 'px'; const seta = b.lastElementChild; seta.style.setProperty('--ax', Math.max(10, Math.min(bw - 18, r.left + r.width / 2 - left - 5)) + 'px'); seta.style.top = emb ? '-5px' : (bh - 5) + 'px'; seta.style.transform = 'rotate(' + (emb ? 45 : 225) + 'deg)';
    requestAnimationFrame(() => { b.style.opacity = '1'; b.style.transform = 'none'; });
    auto = setTimeout(fechar, 8000);
  }
  document.addEventListener('pointerover', e => {
    if (e.pointerType === 'touch' || Date.now() - t0 < 2000) return; const el = e.target instanceof Element && e.target.closest('button,a,[role="button"]'); if (!el || el === alvo || (bal && bal.contains(e.target))) return;
    const it = achar(el); if (!it) return; clearTimeout(tmr); tmr = setTimeout(() => { if (el.matches(':hover')) mostrar(el, it); }, 600);
  }, true);
  document.addEventListener('pointerout', e => { const el = e.target instanceof Element && e.target.closest('button,a,[role="button"]'); if (el && el === alvo && !(e.relatedTarget && bal && bal.contains(e.relatedTarget))) auto = setTimeout(fechar, 350); else if (el && !alvo) clearTimeout(tmr); }, true);
  document.addEventListener('click', e => { const el = e.target instanceof Element && e.target.closest('button,a,[role="button"]'); if (!el || (bal && bal.contains(el))) return; const it = achar(el); if (!it) return; const [a, u] = st(); u.u[it[0]] = (u.u[it[0]] || 0) + 1; grava(a); if (alvo === el) fechar(); }, true);
  window.addEventListener('scroll', () => bal && fechar(), true);
  window.BJDicas = {
    catalogo: () => CAT.map(x => x[0]),
    estado: () => { const [, u] = st(); const dom = CAT.filter(x => (u.u[x[0]] || 0) >= USOS || u.ok[x[0]]); return { desligadas: !!u.desl, experiente: experiente(u), total: CAT.length, dominadas: dom.length, pendentes: CAT.filter(x => !dom.includes(x)).map(x => ({ k: x[0], dica: x[2], usos: u.u[x[0]] || 0, vistas: u.v[x[0]] || 0 })) }; },
    ligar: v => { const [a, u] = st(); u.desl = !v; grava(a); },
    reiniciar: () => { const a = ler(); a[uid()] = { u: {}, v: {}, ok: {}, vt: {}, desl: false }; grava(a); },
  };
})();
